/**
 * Multiple nested generic parameters
 * This tests: Map<String, Map<Integer, List<ProductInfo>>>, List<Map<String, ProductInfo>>
 */
public Map<String, Integer> aggregateInventory(
        Map<String, Map<Integer, List<ProductInfo>>> warehouseData,
        List<Map<String, ProductInfo>> pendingOrders,
        String reportType) {

    Map<String, Integer> result = new HashMap<>();

    // Process warehouse data
    int warehouseTotal = processWarehouseData(warehouseData);
    result.put("warehouseTotal", warehouseTotal);

    // Process pending orders
    int pendingTotal = processPendingOrders(pendingOrders);
    result.put("pendingTotal", pendingTotal);

    System.out.println("Report type: " + reportType);
    return result;
}

