private void logProduct(ProductInfo product) {
    System.out.println("  - " + product);
}

/**
 * Process list of maps with nested generics
 * This tests: List<Map<String, List<ProductInfo>>>
 */
public void processBatchInventory(List<Map<String, List<ProductInfo>>> batches, int batchSize) {
    for (int i = 0; i < batches.size(); i++) {
        Map<String, List<ProductInfo>> batch = batches.get(i);
        processSingleBatch(batch, i, batchSize);
    }
}

/**
 * Process nested Map with complex generics
 * This tests: Map<Integer, Map<String, ProductInfo>>
 */
public int processInventoryMap(Map<Integer, Map<String, ProductInfo>> inventoryMap, String warehouseId) {
    int totalItems = 0;
    for (Map.Entry<Integer, Map<String, ProductInfo>> entry : inventoryMap.entrySet()) {
        Integer shelfId = entry.getKey();
        Map<String, ProductInfo> products = entry.getValue();
        totalItems += processShelf(shelfId, products, warehouseId);
    }
    return totalItems;
}

/**
 * Process pending orders
 */
private int processPendingOrders(List<Map<String, ProductInfo>> pendingOrders) {
    int total = 0;
    for (Map<String, ProductInfo> order : pendingOrders) {
        for (ProductInfo product : order.values()) {
            total += product.getQuantity();
        }
    }
    return total;
}

/**
 * Process a single shelf
 */
private int processShelf(Integer shelfId, Map<String, ProductInfo> products, String warehouseId) {
    System.out.println("Processing shelf " + shelfId + " in warehouse " + warehouseId);
    int count = 0;
    for (ProductInfo product : products.values()) {
        count += product.getQuantity();
        logProduct(product);
    }
    return count;
}

/**
 * Process a single batch
 */
private void processSingleBatch(Map<String, List<ProductInfo>> batch, int batchIndex, int batchSize) {
    System.out.println("Processing batch " + batchIndex + " (size limit: " + batchSize + ")");
    for (Map.Entry<String, List<ProductInfo>> entry : batch.entrySet()) {
        String category = entry.getKey();
        List<ProductInfo> products = entry.getValue();
        System.out.println("  Category: " + category + ", products: " + products.size());
        for (ProductInfo product : products) {
            logProduct(product);
        }
    }
}

/**
 * Process warehouse data
