private int processWarehouseData(Map<String, Map<Integer, List<ProductInfo>>> warehouseData) {
    int total = 0;
    for (Map.Entry<String, Map<Integer, List<ProductInfo>>> warehouse : warehouseData.entrySet()) {
        String warehouseId = warehouse.getKey();
        System.out.println("Warehouse: " + warehouseId);
        for (Map.Entry<Integer, List<ProductInfo>> shelf : warehouse.getValue().entrySet()) {
            for (ProductInfo product : shelf.getValue()) {
                total += product.getQuantity();
            }
        }
    }
    return total;
}

