/**
 * Validates the order, processes payment, runs order processing, then notifies completion.
 * Used by golden file test to verify Javadoc on callee methods.
 */
public Order createAndProcessOrder(Order order, String paymentMethod) {
    // Validate
    orderProcessor.validate(order);

    // Process payment
    PaymentResult paymentResult = paymentService.processPayment(order, paymentMethod);
    if (!paymentResult.isSuccess()) {
        order.setStatus(OrderStatus.FAILED);
        throw new RuntimeException("Payment failed: " + paymentResult.getMessage());
    }

    // Process order
    orderProcessor.process(order);

    notifyCompletion(order);
    return order;
}

private void notifyCompletion(Order order) {
    System.out.println("Order " + order.getId() + " completed");
}

private PaymentResult(boolean success, String message) {
    this.success = success;
    this.message = message;
}

public static PaymentResult failure(String reason) {
    return new PaymentResult(false, reason);
}

public static PaymentResult success() {
    return new PaymentResult(true, "Payment processed successfully");
}

private boolean checkFunds(BigDecimal amount) {
    return amount.compareTo(new BigDecimal("10000")) <= 0;
}

private void executePayment(Order order, String method) {
    System.out.println("Payment executed for order " + order.getId() + " via " + method);
}

public PaymentResult processPayment(Order order, String paymentMethod) {
    if (!validatePaymentMethod(paymentMethod)) {
        return PaymentResult.failure("Invalid payment method");
    }

    if (!checkFunds(order.getAmount())) {
        return PaymentResult.failure("Insufficient funds");
    }

    executePayment(order, paymentMethod);
    return PaymentResult.success();
}

private boolean validatePaymentMethod(String method) {
    return method != null && !method.isBlank();
}

